import { useId, useState } from "react";
import { ClockDial } from "./pickers/clock-dial";
import { NativeSelect } from "./native-select";
import { cn } from "./utils";

type TimeSegments = {
    hour: string;
    minute: string;
    period: string;
};

type TimePickerProps = {
    label: string;
    value: string | null;
    onValueChange: (value: string | null) => void;
    name?: string;
    required?: boolean;
    disabled?: boolean;
    minuteStep?: number;
    locale?: string;
    hourCycle?: "h12" | "h23";
    segmentLabels?: {
        hour: string;
        minute: string;
        period: string;
    };
    className?: string;
};

function readTime(value: string | null, minuteStep: number): number | null {
    if (value === null) return null;
    if (!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value)) {
        throw new RangeError("TimePicker value must be HH:mm or null.");
    }
    const [hour, minute] = value.split(":").map(Number);
    if (minute % minuteStep !== 0) {
        throw new RangeError("TimePicker value must match minuteStep.");
    }
    return hour * 60 + minute;
}

function TimePicker({
    label,
    value,
    onValueChange,
    name,
    required = false,
    disabled = false,
    minuteStep = 5,
    locale = "ko-KR",
    hourCycle,
    segmentLabels,
    className,
}: TimePickerProps) {
    if (!label.trim()) throw new Error("TimePicker requires a label.");
    if (typeof onValueChange !== "function") {
        throw new Error("TimePicker requires onValueChange.");
    }
    if (!Number.isInteger(minuteStep) || minuteStep < 1 ||
        60 % minuteStep !== 0) {
        throw new RangeError("TimePicker minuteStep must divide 60.");
    }
    if (hourCycle !== undefined && hourCycle !== "h12" &&
        hourCycle !== "h23") {
        throw new RangeError("TimePicker hourCycle is not supported.");
    }
    if (segmentLabels && [
        segmentLabels.hour, segmentLabels.minute, segmentLabels.period,
    ].some((text) => typeof text !== "string" || !text.trim())) {
        throw new Error("TimePicker segment labels must not be empty.");
    }
    const minutes = readTime(value, minuteStep);
    const [clockOpen, setClockOpen] = useState(false);
    const clockId = useId();
    const resolvedCycle = hourCycle ?? (
        new Intl.DateTimeFormat(locale, { hour: "numeric" })
            .resolvedOptions().hourCycle?.startsWith("h1")
            ? "h12" : "h23"
    );
    const labels = segmentLabels ?? (locale.toLowerCase().startsWith("ko")
        ? { hour: "시", minute: "분", period: "오전/오후" }
        : { hour: "Hour", minute: "Minute", period: "AM/PM" });
    const digits = new Intl.NumberFormat(locale, {
        useGrouping: false, minimumIntegerDigits: 2,
    });
    const periodFormatter = new Intl.DateTimeFormat(locale, {
        hour: "numeric", hour12: true, timeZone: "UTC",
    });
    const periodLabel = (hour: number, fallback: string) =>
        periodFormatter.formatToParts(new Date(Date.UTC(2020, 0, 1, hour)))
            .find((part) => part.type === "dayPeriod")?.value ?? fallback;
    const periodOptions = [
        { value: "am", label: periodLabel(9, "AM") },
        { value: "pm", label: periodLabel(21, "PM") },
    ];
    const selected: TimeSegments = minutes === null
        ? { hour: "", minute: "", period: "" }
        : {
            hour: String(resolvedCycle === "h12"
                ? Math.floor(minutes / 60) % 12 || 12
                : Math.floor(minutes / 60)).padStart(2, "0"),
            minute: String(minutes % 60).padStart(2, "0"),
            period: minutes < 12 * 60 ? "am" : "pm",
        };
    const [draft, setDraft] = useState<{
        source: string | null;
        cycle: "h12" | "h23";
        segments: TimeSegments;
    } | null>(null);
    const segments = draft?.source === value && draft.cycle === resolvedCycle
        ? draft.segments : selected;
    const hasPartial = Object.values(segments).some(Boolean);

    function change(part: keyof TimeSegments, nextValue: string) {
        const next = { ...segments, [part]: nextValue };
        const complete = next.hour !== "" && next.minute !== "" &&
            (resolvedCycle === "h23" || next.period !== "");
        if (!complete) {
            if (value !== null) onValueChange(null);
            setDraft({ source: null, cycle: resolvedCycle, segments: next });
            return;
        }
        const hour = resolvedCycle === "h12"
            ? Number(next.hour) % 12 + (next.period === "pm" ? 12 : 0)
            : Number(next.hour);
        setDraft(null);
        onValueChange(
            `${String(hour).padStart(2, "0")}:${next.minute}`,
        );
    }

    const showClock = resolvedCycle === "h23" && clockOpen;
    const clockLabel = locale.toLowerCase().startsWith("ko") ? "시계로 선택" : "Select using clock";
    const hours = resolvedCycle === "h12"
        ? [12, ...Array.from({ length: 11 }, (_, index) => index + 1)]
        : Array.from({ length: 24 }, (_, index) => index);

    return (
        <fieldset className={cn("m-0 min-w-0 border-0 p-0", className)}
            disabled={disabled}>
            <legend className="mb-2 text-sm font-medium text-foreground">
                {label}{required && <span aria-hidden="true"> *</span>}
            </legend>
            {name && <input type="hidden" name={name} value={value ?? ""}
                disabled={disabled} />}
            <div className={cn("grid min-w-0 gap-2",
                resolvedCycle === "h12" ? "grid-cols-3" : "grid-cols-2")}
            >
                <NativeSelect value={segments.hour} disabled={disabled}
                    required={required || hasPartial}
                    aria-label={`${label} · ${labels.hour}`}
                    onChange={(event) => change("hour", event.target.value)}
                    className="min-w-0 px-2 pr-7">
                    <option value="">{labels.hour}</option>
                    {hours.map((hour) => {
                        const text = String(hour).padStart(2, "0");
                        return <option key={text} value={text}>
                            {digits.format(hour)}
                        </option>;
                    })}
                </NativeSelect>
                <NativeSelect value={segments.minute} disabled={disabled}
                    required={required || hasPartial}
                    aria-label={`${label} · ${labels.minute}`}
                    onChange={(event) => change("minute", event.target.value)}
                    className="min-w-0 px-2 pr-7">
                    <option value="">{labels.minute}</option>
                    {Array.from({ length: 60 / minuteStep }, (_, index) => {
                        const minute = index * minuteStep;
                        const text = String(minute).padStart(2, "0");
                        return <option key={text} value={text}>
                            {digits.format(minute)}
                        </option>;
                    })}
                </NativeSelect>
                {resolvedCycle === "h12" && (
                    <NativeSelect value={segments.period} disabled={disabled}
                        required={required || hasPartial}
                        aria-label={`${label} · ${labels.period}`}
                        onChange={(event) => change(
                            "period", event.target.value,
                        )}
                        className="min-w-0 px-2 pr-7">
                        <option value="">{labels.period}</option>
                        {periodOptions.map((option) => (
                            <option key={option.value} value={option.value}>
                                {option.label}
                            </option>
                        ))}
                    </NativeSelect>
                )}
            </div>
            {resolvedCycle === "h23" && (
                <button type="button" aria-expanded={showClock} aria-controls={showClock ? clockId : undefined}
                    onClick={() => setClockOpen(!clockOpen)}
                    className="mt-2 rounded-sm border border-border px-3 py-1 text-sm hover:bg-surface-subtle">
                    {clockLabel}
                </button>
            )}
            {showClock && <div id={clockId} className="mt-3">
                <ClockDial hour={Number(segments.hour)} minute={Number(segments.minute)}
                    hourLabel={labels.hour} minuteLabel={labels.minute}
                    disabled={disabled} minuteStep={minuteStep}
                    onHourChange={hour => change("hour", String(hour % 24).padStart(2, "0"))}
                    onMinuteChange={minute => {
                        setDraft(null);
                        onValueChange(`${segments.hour || "00"}:${String(minute).padStart(2, "0")}`);
                    }} />
            </div>}
        </fieldset>
    );
}

export { TimePicker };
export type { TimePickerProps };

import { useEffect, useId, useRef, useState } from "react";
import type { KeyboardEvent, MouseEvent } from "react";
import { cn } from "../utils";

type ClockDialProps = {
    hour: number;
    minute: number;
    onHourChange: (hour: number) => void;
    onMinuteChange: (minute: number) => void;
    minuteStep?: number;
    duration?: boolean;
    disabled?: boolean;
    hourLabel?: string;
    minuteLabel?: string;
};

const hours = Array.from({ length: 25 }, (_, hour) => hour);
const formatNumber = (value: number) => String(value).padStart(2, "0");
const angle = (index: number, positions: number) => index * Math.PI * 2 / positions;

function dialPosition(index: number, positions: number, radius: number) {
    const radians = angle(index, positions);
    return { left: `${50 + Math.sin(radians) * radius}%`, top: `${50 - Math.cos(radians) * radius}%` };
}

function ClockDial({
    hour, minute, onHourChange, onMinuteChange, minuteStep = 1,
    duration = false, disabled = false, hourLabel = "시", minuteLabel = "분",
}: ClockDialProps) {
    const [part, setPart] = useState<"hour" | "minute">("hour");
    const [hourFocus, setHourFocus] = useState(hour);
    const pendingFocus = useRef(false);
    const dialRef = useRef<HTMLDivElement>(null);
    const dialId = useId();
    const minuteMode = part === "minute";
    const selectedMinute = minute % 60;
    const labelInterval = Math.max(5, minuteStep);
    const minuteMarks = Array.from({ length: 60 / minuteStep }, (_, index) => index * minuteStep)
        .filter(value => value % labelInterval === 0 || value === selectedMinute);

    useEffect(() => {
        if (pendingFocus.current) {
            pendingFocus.current = false;
            dialRef.current?.querySelector<HTMLButtonElement>("[tabindex='0']")?.focus();
        }
    }, [part, hourFocus, selectedMinute]);

    function chooseHour(value: number) {
        onHourChange(value);
        pendingFocus.current = true;
        setPart("minute");
    }

    function moveDial(event: KeyboardEvent<HTMLButtonElement>, value: number) {
        const offsets = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 };
        const offset = offsets[event.key as keyof typeof offsets];
        if (offset === undefined && event.key !== "Home" && event.key !== "End") return;
        event.preventDefault();
        event.stopPropagation();
        const count = minuteMode ? 60 / minuteStep : hours.length;
        const current = minuteMode ? value / minuteStep : value;
        const next = event.key === "Home" ? 0 : event.key === "End" ? count - 1 : (current + (offset ?? 0) + count) % count;
        if (next === current) return;
        pendingFocus.current = true;
        if (minuteMode) onMinuteChange(next * minuteStep);
        else setHourFocus(next);
    }

    function chooseMinuteOnFace(event: MouseEvent<HTMLButtonElement>) {
        const box = event.currentTarget.getBoundingClientRect();
        const x = event.clientX - box.left - box.width / 2;
        const y = event.clientY - box.top - box.height / 2;
        if (Math.hypot(x, y) < box.width * 0.15) return;
        const turns = (Math.atan2(x, -y) / (2 * Math.PI) + 1) % 1;
        const steps = 60 / minuteStep;
        onMinuteChange(Math.round(turns * steps) % steps * minuteStep);
    }

    const handIndex = minuteMode ? selectedMinute : hour % 12;
    const shortHand = minuteMode ? selectedMinute % labelInterval !== 0 : hour > 12;
    const handRadius = shortHand ? 25 : 40;

    return <div className="mx-auto grid w-full max-w-68 min-w-0 justify-items-center gap-2" data-ui="clock-dial">
        <div className="flex items-center gap-2 tabular-nums">
            <button type="button" disabled={disabled} aria-pressed={!minuteMode} aria-controls={dialId}
                className="rounded-sm border border-border px-3 py-1 text-sm aria-pressed:border-accent aria-pressed:bg-accent aria-pressed:text-accent-foreground"
                onClick={() => { setHourFocus(hour); setPart("hour"); }}>{formatNumber(hour)} {hourLabel}</button>
            <span aria-hidden="true">:</span>
            <button type="button" disabled={disabled} aria-pressed={minuteMode} aria-controls={dialId}
                className="rounded-sm border border-border px-3 py-1 text-sm aria-pressed:border-accent aria-pressed:bg-accent aria-pressed:text-accent-foreground"
                onClick={() => setPart("minute")}>{formatNumber(minute)} {minuteLabel}</button>
        </div>
        <div ref={dialRef} id={dialId} role="group" aria-label={minuteMode ? minuteLabel : hourLabel}
            className="relative aspect-square w-full rounded-full bg-surface-subtle text-foreground tabular-nums">
            {minuteMode && <span aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-full text-muted/60"
                style={{ background: `repeating-conic-gradient(currentColor 0deg 0.6deg, transparent 0.6deg ${minuteStep * 6}deg)`,
                    maskImage: "radial-gradient(transparent 66%, black 66% 69%, transparent 69%)" }} />}
            {minuteMode && <button type="button" tabIndex={-1} aria-hidden="true" disabled={disabled}
                className="absolute inset-0 size-full rounded-full" onMouseDown={event => event.preventDefault()}
                onClick={chooseMinuteOnFace} />}
            {(minuteMode || hour !== 0) && <span aria-hidden="true" className="pointer-events-none absolute bottom-1/2 left-1/2 w-px origin-bottom bg-accent"
                style={{ height: `${handRadius}%`, transform: `rotate(${handIndex * (minuteMode ? 6 : 30)}deg)` }} />}
            {minuteMode && <span aria-hidden="true" className="pointer-events-none absolute top-1/2 left-1/2 size-2 -translate-1/2 rounded-full bg-accent" />}
            {(minuteMode ? minuteMarks : hours).map(value => {
                const selected = value === (minuteMode ? selectedMinute : hour);
                const inner = minuteMode ? value % labelInterval !== 0 : value >= 13;
                const position = !minuteMode && value === 0 ? { left: "50%", top: "50%" }
                    : dialPosition(minuteMode ? value : value % 12, minuteMode ? 60 : 12, inner ? 25 : 40);
                return <button key={value} type="button" style={position} disabled={disabled}
                    tabIndex={value === (minuteMode ? selectedMinute : hourFocus) ? 0 : -1}
                    aria-label={`${formatNumber(value)} ${minuteMode ? minuteLabel : hourLabel}`}
                    aria-pressed={selected} onFocus={() => { if (!minuteMode) setHourFocus(value); }}
                    data-clock-hour={minuteMode ? undefined : value} data-clock-minute={minuteMode ? value : undefined}
                    onClick={() => minuteMode ? onMinuteChange(value) : chooseHour(value)}
                    onKeyDown={event => moveDial(event, value)}
                    className={cn("absolute -translate-1/2 rounded-full leading-none focus-visible:z-10",
                        inner ? "size-[12%] text-xs" : "size-[14%] text-sm",
                        selected ? "bg-accent text-accent-foreground" : "bg-surface-subtle hover:bg-surface")}>{formatNumber(value)}</button>;
            })}
        </div>
        {minuteMode && (duration
            ? <button type="button" disabled={disabled} className="rounded-sm border border-border px-3 py-1 text-sm hover:bg-surface-subtle"
                onClick={() => onMinuteChange(60)}>60 {minuteLabel}</button>
            : <span className="text-xs text-muted">00 / 60 {minuteLabel}</span>)}
    </div>;
}

export { ClockDial };
